// End-to-end test of the built-in site editor + blog engine via headless Chrome + CDP.
// Run:  node tools/e2e/e2e_test.mjs   (from anywhere; paths self-locate)
// Requires: node 22+ (native WebSocket/fetch), Chrome, py launcher (http.server).
// The harness starts its own local server and Chrome, and cleans both up.
import { spawn, spawnSync } from "node:child_process";
import { readFileSync, readdirSync, mkdtempSync, writeFileSync, copyFileSync, cpSync, existsSync, unlinkSync } from "node:fs";
import vm from "node:vm";
import { tmpdir } from "node:os";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { deflateSync } from "node:zlib";
import { createHash } from "node:crypto";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
// The engine's folder, from the site root. Every trunk is in it.
const LIB = "libraries/harrisxrwebengine/";
// The host's facts, as a page reads them: site.config.js, run on its own.
// The text is what a fake repo folder holds, because the folder route
// knows a site by the siteId in its own site.config.js.
const SITE_CONFIG_TEXT = readFileSync(join(REPO, "site.config.js"), "utf8");
const SITE_CONFIG = (() => {
  const ctx = {};
  ctx.window = ctx;
  vm.createContext(ctx);
  vm.runInContext(SITE_CONFIG_TEXT, ctx);
  return ctx.AMH.config;
})();
const SERVER_PORT = 8123;
const PAGE = `http://127.0.0.1:${SERVER_PORT}/index.html`;
const BLOGPAGE = `http://127.0.0.1:${SERVER_PORT}/blog.html`;
const CHROME = "c:/Program Files/Google/Chrome/Application/chrome.exe";
const DEBUG_PORT = 9225;

const results = [];
function check(name, ok, detail) {
  results.push({ name, ok, detail: detail || "" });
  console.log((ok ? "PASS" : "FAIL") + "  " + name + (detail ? "  [" + detail + "]" : ""));
}

// self-contained: serve the repo ourselves for the duration of the run
// The suite serves a COPY of the repo, not the repo, so the content of the
// three pages can be fixed without touching the site. See fixedPage(). The
// engine's folder is copied whole, so a file added to it needs no line here.
const SERVE = mkdtempSync(join(tmpdir(), "ced-serve-"));
for (const f of ["site.css", "site.config.js", "aaron-portfolio-portrait-transparent.png"]) {
  try { copyFileSync(join(REPO, f), join(SERVE, f)); } catch {}
}
for (const page of ["index.html", "gallery.html", "blog.html"]) {
  writeFileSync(join(SERVE, page), fixedPage(page, readFileSync(join(REPO, page), "utf-8")));
}
for (const d of ["img", "tools", "libraries"]) {
  try { cpSync(join(REPO, d), join(SERVE, d), { recursive: true }); } catch {}
}
// The engine's second site, Greenline Mowing, from tools/e2e/fixtures/lawn/.
// It is served at /lawn/ on this origin with this commit's engine copied
// under it, because the fixture holds no engine of its own. lawnpin is the
// same site pinned to a release no engine has, and amhpin is this site's
// blog page pinned the same way. The LW section reads all three.
const LAWN_FIXTURE = join(REPO, "tools", "e2e", "fixtures", "lawn");
const LAWN_CONFIG_TEXT = readFileSync(join(LAWN_FIXTURE, "site.config.js"), "utf8");
const wrongPin = (text) => text.replace(/engineVersion: "[^"]*"/, 'engineVersion: "0.0.0"');
for (const d of ["lawn", "lawnpin"]) {
  cpSync(LAWN_FIXTURE, join(SERVE, d), { recursive: true });
  cpSync(join(REPO, LIB), join(SERVE, d, LIB), { recursive: true });
}
writeFileSync(join(SERVE, "lawnpin", "site.config.js"), wrongPin(LAWN_CONFIG_TEXT));
cpSync(join(REPO, LIB), join(SERVE, "amhpin", LIB), { recursive: true });
for (const f of ["blog.html", "site.css"]) copyFileSync(join(SERVE, f), join(SERVE, "amhpin", f));
writeFileSync(join(SERVE, "amhpin", "site.config.js"), wrongPin(SITE_CONFIG_TEXT));
const server = spawn("py", ["-3", "-m", "http.server", String(SERVER_PORT), "--bind", "127.0.0.1"],
  { cwd: SERVE, stdio: "ignore" });
await new Promise((r) => setTimeout(r, 1500));

const profile = mkdtempSync(join(tmpdir(), "ced-e2e-"));
const chrome = spawn(CHROME, [
  "--headless=new", "--disable-gpu", "--no-first-run", "--mute-audio",
  "--remote-debugging-port=" + DEBUG_PORT,
  "--user-data-dir=" + profile,
  PAGE,
], { stdio: "ignore" });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// minimal STORE-zip reader: buffer -> { name: Buffer }
function unzipStore(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const out = {};
  let off = 0;
  while (off + 4 <= buf.length && dv.getUint32(off, true) === 0x04034b50) {
    const size = dv.getUint32(off + 22, true);
    const nameLen = dv.getUint16(off + 26, true);
    const extraLen = dv.getUint16(off + 28, true);
    const name = buf.slice(off + 30, off + 30 + nameLen).toString("utf8");
    const start = off + 30 + nameLen + extraLen;
    out[name] = buf.slice(start, start + size);
    off = start + size;
  }
  return out;
}

// page-side patch: capture the next download's bytes as base64 in window.__zipB64
const ZIP_CAPTURE = `
  window.__zipB64 = null;
  HTMLAnchorElement.prototype.click = function () {
    if (!this.download) return;
    fetch(this.href).then(r => r.blob()).then(b => new Promise(res => {
      var fr = new FileReader();
      fr.onload = () => res(fr.result.split(',')[1]);
      fr.readAsDataURL(b);
    })).then(b64 => { window.__zipB64 = b64; });
  };`;

// The media files the suite makes, as tools/e2e/fixtures/media.js makes
// them in the page: window.__media builds a WAV, a MIDI file and media
// headers from bytes, and a recording. The harness runs it in the page.
const MEDIA_FIX = readFileSync(join(REPO, "tools", "e2e", "fixtures", "media.js"), "utf-8");

// The wizard box, measured. A publish is one job with several screens, so
// the box must be one box: the same height, and the buttons in the same
// place, from Confirm to Done. It used to take its height from whichever
// screen was up, and because it is centred by a transform it re-centred
// itself each time, walking the buttons up and down the screen.
//
// Declared page-side once and called from each step's probe, so the three
// measurements are taken exactly the same way.
const WIZ_GEO = `
  window.WIZ_GEO = function (box) {
    var r = box.getBoundingClientRect();
    var bt = box.querySelector('.ced-modal__btns');
    var body = box.querySelector('.bc-wiz__body');
    /* the BOTTOM of the button row is the zone: the row is the last child
       of a fixed-height box, so its bottom edge is the same on every step,
       and any button that exists sits against it. Its top moves, because
       the progress step has no buttons and the empty row is shorter. */
    return { top: Math.round(r.top), h: Math.round(r.height),
             btnBottom: bt ? Math.round(bt.getBoundingClientRect().bottom) : null,
             btnTop: bt ? Math.round(bt.getBoundingClientRect().top) : null,
             /* the body scrolls rather than pushing the box open, which is
                what keeps the buttons in place on a step that overruns */
             over: body ? body.scrollHeight > body.clientHeight + 1 : null,
             /* by how much. "over" alone says a step outgrew the box but
                not whether it did so by a line or by a paragraph, and the
                answer decides whether the head or the step is at fault. */
             slack: body ? body.clientHeight - body.scrollHeight : null,
             headH: box.querySelector('.ced-modal__head')
               ? Math.round(box.querySelector('.ced-modal__head').getBoundingClientRect().height)
               : 0 };
  };`;

// The search index, read out of the file a publish wrote. Since V057 the
// file is one assignment holding readable JSON, so the table is the object
// in it and there is nothing to decompress.
function searchTable(fileText) {
  const t = String(fileText);
  const open = t.indexOf("{"), close = t.lastIndexOf("}");
  if (open < 0 || close < open) return { error: "no table in search.js" };
  try { return JSON.parse(t.slice(open, close + 1)); }
  catch (e) { return { error: e.message }; }
}
// The image index, images.js: the same shape, one statement holding a
// record, read the same way.
function imagesTable(fileText) {
  const t = String(fileText);
  const open = t.indexOf("{"), close = t.lastIndexOf("}");
  if (open < 0 || close < open) return { error: "no record in images.js", images: [] };
  try { return JSON.parse(t.slice(open, close + 1)); }
  catch (e) { return { error: e.message, images: [] }; }
}
// A run of base64 long enough to be a payload rather than a word. A
// thumbnail is a data: URI and is base64 by its nature, so it is taken out
// first: what must not be in the file is a payload, which is what made a
// scanner call the old packed index a dangerous file.
function hasBase64Blob(text) {
  const withoutThumbs = String(text)
    .replace(/data:[a-z/+.-]+;base64,[A-Za-z0-9+/=]+/g, "");
  return /[A-Za-z0-9+/]{60,}={0,2}/.test(withoutThumbs);
}

// remove the CONTENT of the named regions from a source string, so two files
// can be compared for byte-identity everywhere outside those regions.
// note: a slug whose span nests other markers (deepdive) covers them too.
function stripSpans(txt, slugs) {
  let out = txt;
  for (const s of slugs) {
    const open = `<!--[edit:${s}]-->`, close = `<!--[/edit:${s}]-->`;
    const a = out.indexOf(open);
    const b = out.indexOf(close, a);
    if (a < 0 || b < 0) return null;
    out = out.slice(0, a + open.length) + out.slice(b);
  }
  return out;
}


