    var help = document.querySelector('.bc-panel .ced-spec__btn');
    if (!card || !body || !help) return { card: !!card, body: !!body, help: !!help };
    var num = (/(\\d{4})/.exec(card.querySelector('.bc-card__meta').textContent) || [])[1] || '';
